From 9d4722b60d1e52ca49ca3a350409d83a4e251c8c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:46:05 +0100
Subject: [PATCH] daemon: Trust UPower's battery level for peripheral low
 battery alerts

Devices like Logitech mice only report a coarse level, and UPower marks
the percentage it derives as one to ignore, yet it still triggered alerts.
For such devices, notify only when the level itself is low or critical.

BUG: 457893
---
 daemon/powerdevilcore.cpp | 20 ++++++++++++++++++++
 1 file changed, 20 insertions(+)

diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..b04d24165 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -35,7 +35,9 @@

 #include <QDBusConnection>
 #include <QDBusConnectionInterface>
+#include <QDBusReply>
 #include <QDBusServiceWatcher>
+#include <QDBusVariant>
 #include <QTimer>

 #include <QDebug>
@@ -533,6 +535,24 @@ bool Core::emitBatteryChargePercentNotification(int currentPercent, int previous
             return false;
         }

+        // Devices reporting a coarse battery level only have an approximate percentage
+        // (UPower prints it as "should be ignored"), so trust the level they report instead
+        if (udi.startsWith(QLatin1String("/org/freedesktop/UPower/"))) {
+            QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.UPower"),
+                                                              udi,
+                                                              QStringLiteral("org.freedesktop.DBus.Properties"),
+                                                              QStringLiteral("Get"));
+            msg << QStringLiteral("org.freedesktop.UPower.Device") << QStringLiteral("BatteryLevel");
+            const QDBusReply<QDBusVariant> reply = QDBusConnection::systemBus().call(msg);
+            if (reply.isValid()) {
+                // UpDeviceLevel: 1 is None (no coarse level), 3 is Low, 4 is Critical
+                const uint level = reply.value().variant().toUInt();
+                if (level != 1 && level != 3 && level != 4) {
+                    return false;
+                }
+            }
+        }
+
         {
             QString name = device.product();
             if (!device.vendor().isEmpty()) {
